OUT=Path(__file__).resolve().parent
changes={}
def q(n,ru,en,tr):
    changes[f'Q-{n}']={l:{'question':s} for l,s in zip(('ru','en','tr'),(ru,en,tr))}
def td(n,field,ru,en,tr):
    card=changes.setdefault(f'TD-{n}',{})
    for l,s in zip(('ru','en','tr'),(ru,en,tr)):card.setdefault(l,{})[field]=s
def y(n,ru,en,tr):
    first,sep,rest=tr.partition('.')
    turkish='{P1}, {P2} ile '+first+' öner.'+(rest if sep else '')
    changes[f'YB-{n}']={'ru':{'proposal':'{P1}, предложи {P2}: '+ru},'en':{'proposal':'{P1}, suggest to {P2}: '+en},'tr':{'proposal':turkish}}

