td(1141,'truth','{P1} и {P2}, если оба хотите, напишите в личном чате: что вас больше радует в совместной фантазии — неожиданная деталь или общий финал?','{P1} and {P2}, if you both wish, write in private chat: what do you enjoy more in a shared fantasy, an unexpected detail or a joint ending?','{P1} ve {P2}, ikiniz de isterseniz özel sohbete yazın: ortak hayalde beklenmedik ayrıntı mı birlikte bulunan son mu daha hoşunuza gider?')
td(1141,'dare','{P1} и {P2}, если оба хотите, в личном чате по одной строке добавьте приятную вам деталь в общий вымышленный сад.','{P1} and {P2}, if you both wish, each add one line in private chat with a detail you enjoy in a shared imaginary garden.','{P1} ve {P2}, ikiniz de isterseniz ortak hayali bahçeye hoşunuza giden birer ayrıntıyı özel sohbette tek satırla ekleyin.')
td(1143,'dare','{P1} и {P2}, если оба хотите, напишите в личном чате две реплики: сказочный кот просит сову помочь придумать имя звезде. Это сценка, не реальная просьба.','{P1} and {P2}, if you both wish, write two lines in private chat: a fairy-tale cat asks an owl to help name a star. This is roleplay, not a real request.','{P1} ve {P2}, ikiniz de isterseniz özel sohbette iki replik yazın: masal kedisi yıldızı adlandırmak için baykuştan yardım istiyor. Bu gerçek istek değil, sahne.')
td(1144,'dare','{P1} и {P2}, если оба хотите, в личном чате придумайте два разных спасибо от сказочных персонажей: одно торжественное, другое совсем простое.','{P1} and {P2}, if you both wish, invent two contrasting fairy-tale thank-yous in private chat: one grand and one very simple.','{P1} ve {P2}, ikiniz de isterseniz özel sohbette masal karakterlerinden iki farklı teşekkür bulun: biri gösterişli, biri çok sade.')

# Replacement meanings: explicit new truth/dare pairs, still draft, same stable ID at r2.
for n,ru,en,tr in [
 (1023,('Ты предпочёл бы суп, который рассказывает сказки, или суп, который меняет цвет?','Придумай короткую историю о супе, сбежавшем из тарелки.'),('Would you prefer soup that tells fairy tales or soup that changes colour?','Invent a short story about soup escaping its bowl.'),('Masal anlatan çorba mı renk değiştiren çorba mı seçerdin?','Kâseden kaçan çorba hakkında kısa bir hikâye bul.')),
 (1024,('Какой предмет ты взял бы на встречу с говорящим деревом?','Опиши, как выбранный предмет удивил говорящее дерево.'),('What object would you take to meet a talking tree?','Describe how that object surprised the talking tree.'),('Konuşan ağaçla buluşmaya hangi nesneyi götürürdün?','O nesnenin konuşan ağacı nasıl şaşırttığını anlat.')),
 (1027,('Какую начинку ты выбрал бы для пиццы на Луне?','Придумай, как лунная пицца убежала от невесомого сыра.'),('What topping would you choose for pizza on the Moon?','Imagine how a lunar pizza escaped weightless cheese.'),('Ayda pizza için hangi malzemeyi seçerdin?','Ay pizzasının ağırlıksız peynirden nasıl kaçtığını hayal et.')),
 (1029,('Какую вещь ты превратил бы в маленького сказочного питомца?','Опиши его первую безобидную шалость.'),('Which object would you turn into a tiny fairy-tale pet?','Describe its first harmless prank.'),('Hangi nesneyi küçük masal hayvanına dönüştürürdün?','İlk zararsız yaramazlığını anlat.')),
 (1032,('Ты выбрал бы лишний час утра или лишний час вечера?','Придумай, что делает потерявшийся час на сказочной площади.'),('Would you choose an extra morning hour or evening hour?','Imagine what a lost hour does in a fairy-tale square.'),('Ek bir sabah saati mi akşam saati mi seçerdin?','Kaybolmuş bir saatin masal meydanında ne yaptığını hayal et.')),
 (1034,('На чём ты поплыл бы по морю лимонада: на льдинке или лимонной дольке?','Опиши встречу своего кораблика с сонной соломинкой.'),('Would you sail a lemonade sea on ice or a lemon slice?','Describe your boat meeting a sleepy straw.'),('Limonata denizinde buzla mı limon dilimiyle mi yüzerdin?','Teknenin uykulu pipetle karşılaşmasını anlat.')),
 (1036,('Какой запах воображаемого парка тебе был бы интересен?','Придумай, что увидел гуляющий по парку будильник.'),('Which imaginary park scent would interest you?','Imagine what an alarm clock saw while walking in the park.'),('Hayali parkın hangi kokusu ilgini çekerdi?','Parkta dolaşan çalar saatin ne gördüğünü hayal et.')),
 (1038,('Ты предпочёл бы музыку для облачного поезда или подводного лифта?','Опиши словами, как эта музыка неожиданно меняет настроение.'),('Would you prefer music for a cloud train or an underwater lift?','Describe in words how that music unexpectedly changes mood.'),('Bulut treni mi su altı asansörü mü, hangisinin müziğini seçerdin?','Bu müziğin havasının beklenmedik biçimde değişmesini sözcüklerle anlat.')),
 (1040,('Какой звук ты сохранил бы в воображаемой ракушке?','Придумай, какой ответ ракушка даст тишине.'),('Which sound would you keep in an imaginary shell?','Imagine the shell’s reply to silence.'),('Hayali deniz kabuğunda hangi sesi saklardın?','Deniz kabuğunun sessizliğe vereceği cevabı bul.')),
 (1042,('Какой сказочный инструмент ты хотел бы увидеть в оркестре дождя?','Опиши встречу этого инструмента с первой каплей.'),('Which fairy-tale instrument would you like in a rain orchestra?','Describe that instrument meeting the first raindrop.'),('Yağmur orkestrasında hangi masal çalgısını görmek isterdin?','O çalgının ilk damlayla karşılaşmasını anlat.')),
 (1043,('Какая музыка подошла бы прогулке по перевёрнутому городу?','Придумай одну строку от имени мелодии, потерявшей свои ноты.'),('What music would suit a walk in an upside-down city?','Invent one line from a tune that has lost its notes.'),('Ters dönmüş şehirde yürüyüşe hangi müzik yakışırdı?','Notalarını kaybeden melodinin ağzından bir cümle bul.')),
 (1044,('Где ты предпочёл бы воображаемый концерт: на облаке или в ракушке?','Опиши одно неожиданное событие на выбранном концерте.'),('Would you prefer an imaginary concert on a cloud or inside a shell?','Describe one unexpected event at that concert.'),('Hayali konseri bulutta mı deniz kabuğunda mı isterdin?','Seçtiğin konserdeki beklenmedik bir olayı anlat.')),
 (1048,('Кто интереснее сыграл бы музыку утра: птицы или чайники?','Придумай добрую перепалку этих двух оркестров.'),('Who would play more interesting morning music: birds or kettles?','Imagine a friendly argument between those two orchestras.'),('Sabah müziğini kuşlar mı çaydanlıklar mı daha ilginç çalardı?','Bu iki orkestranın dostça atışmasını hayal et.')),
 (1069,('Какое маленькое приключение ты выбрал бы для первого дня в сказочном клубе?','Представь нового участника клуба летающих закладок одной смешной деталью.'),('Which small adventure would you choose for your first day in a fairy-tale club?','Introduce a newcomer to the flying-bookmark club with one funny detail.'),('Masal kulübündeki ilk gün için hangi küçük macerayı seçerdin?','Uçan ayraç kulübünün yeni üyesini komik bir ayrıntıyla tanıt.')),
 (1071,('Какое растение ты хотел бы видеть спутником в сказочном путешествии?','Опиши, как оно помогает другу выбрать дорогу.'),('Which plant would you choose as a fairy-tale travel companion?','Describe it helping a friend choose a route.'),('Masal yolculuğunda hangi bitki arkadaşın olsun isterdin?','Arkadaşına yol seçerken nasıl yardım ettiğini anlat.')),
 (1073,('Ты выбрал бы вечер дружеских историй или совместных загадок?','Придумай начало истории, которую могла бы продолжить вся компания.'),('Would you choose an evening of friends’ stories or shared riddles?','Invent the opening of a story that a whole group could continue.'),('Arkadaş hikâyeleri akşamı mı ortak bilmeceler mi seçerdin?','Bütün grubun sürdürebileceği hikâyenin başlangıcını bul.')),
 (1075,('Какую воображаемую вещь ты одолжил бы другу: карманное солнце или тихое эхо?','Расскажи короткую сцену возвращения этой вещи.'),('Which imaginary thing would you lend a friend: pocket sunshine or a quiet echo?','Tell a short scene about returning it.'),('Arkadaşına cep güneşi mi sessiz yankı mı ödünç verirdin?','O şeyin geri verildiği kısa bir sahne anlat.')),
 (1076,('Какая общая привычка друзей кажется тебе уютной? Можно придумать её.','Придумай забавную традицию друзей из города движущихся мостов.'),('Which shared habit of friends seems cosy to you? You may invent one.','Invent a funny tradition of friends in a city of moving bridges.'),('Arkadaşların hangi ortak alışkanlığı sana sıcak gelir? Uydurabilirsin.','Hareketli köprüler şehrindeki arkadaşlara komik bir gelenek bul.')),
 (1079,('Какое сказочное увлечение ты разделил бы с другом?','Придумай, как два друга нашли общий интерес к коллекционированию теней.'),('Which fairy-tale hobby would you share with a friend?','Imagine two friends discovering a shared interest in collecting shadows.'),('Hangi masal hobisini arkadaşınla paylaşırdın?','İki arkadaşın gölge toplama merakını nasıl keşfettiğini hayal et.')),
 (1080,('Как ты хотел бы закончить вымышленное приключение с компанией?','Придумай один смешной сувенир для каждого участника сказочной экспедиции.'),('How would you end an imaginary group adventure?','Invent a funny souvenir for each member of a fairy-tale expedition.'),('Grupla hayali macera nasıl bitsin isterdin?','Masal gezisinin her üyesi için komik bir hatıra bul.')),
 (1082,('Какой совместный замысел с другом тебе приятнее вообразить: дом на дереве или сад в чемодане?','Опиши неожиданного гостя в вашем воображаемом саду в чемодане.'),('Which shared idea with a friend sounds nicer: a treehouse or a suitcase garden?','Describe an unexpected visitor to your imaginary suitcase garden.'),('Arkadaşınla ağaç ev mi bavul bahçesi mi hayal etmek istersin?','Hayali bavul bahçenizin beklenmedik misafirini anlat.')),
 (1083,('Какую маленькую находку ты показал бы другу в стране крошечных вещей?','Расскажи, как два сказочных друга искали пропавшую запятую.'),('What little discovery would you show a friend in the land of tiny things?','Tell how two fairy-tale friends searched for a missing comma.'),('Minik şeyler ülkesinde hangi buluşu arkadaşına gösterirdin?','İki masal arkadaşının kayıp virgülü nasıl aradığını anlat.')),
 (1142,('Что тебе приятнее в совместной фантазии: придумывать место или персонажей?','В личном чате добавьте по одной неожиданной детали к воображаемой карте острова.'),('What do you enjoy more in a shared fantasy: inventing places or characters?','In private chat, each add an unexpected detail to an imaginary island map.'),('Ortak hayalde yer mi karakter mi bulmayı daha çok seversin?','Özel sohbette hayali ada haritasına birer beklenmedik ayrıntı ekleyin.')),
 (1145,('Какую деталь ты первым заметил бы на вымышленном празднике друга?','В личном чате по одной фразе опишите появление сказочного гостя на празднике.'),('What detail would you notice first at a friend’s imaginary celebration?','In private chat, each describe a fairy-tale guest arriving at the celebration in one line.'),('Arkadaşının hayali kutlamasında önce hangi ayrıntıyı fark ederdin?','Özel sohbette kutlamaya gelen masal misafirini birer cümleyle anlatın.')),
 (1074,('Что ты выбрал бы для компании друзей: прогулку по крыше сказки или пикник под землёй?','Придумай одну неожиданную остановку для такой прогулки.'),('For friends, would you choose a walk on a fairy tale’s roof or an underground picnic?','Invent an unexpected stop for that walk.'),('Arkadaşlarla masal çatısında yürüyüş mü yer altında piknik mi seçerdin?','O yürüyüş için beklenmedik bir durak bul.')),
]:
 for field,index in [('truth',0),('dare',1)]:
  prefix={'ru':'{P1}, ','en':'{P1}, ','tr':'{P1}, '}
  if n>=1101:
   prefix={'ru':'{P1} и {P2}, если оба хотите, в личном чате: ','en':'{P1} and {P2}, if you both wish, in private chat: ','tr':'{P1} ve {P2}, ikiniz de isterseniz özel sohbette: '}
  td(n,field,prefix['ru']+ru[index],prefix['en']+en[index],prefix['tr']+tr[index])

y(1005,'вместе придумать, какое необычное событие произойдёт на концерте космического дуэта, а не название дуэта.','imagine together an unusual event at a space duet’s concert, rather than naming the duet.','uzay düetini adlandırmak yerine konserinde birlikte sıra dışı bir olay hayal etmeyi.')
y(1007,'по очереди добавить по одному звуку в воображаемый утренний хор сонных чайников; звуки можно описать словами.','take turns adding a sound to an imaginary morning choir of sleepy kettles; sounds may be described in words.','uykulu çaydanlıkların hayali sabah korosuna sırayla birer ses eklemeyi; sesleri sözcüklerle anlatabilirsiniz.')
y(1013,'придумать короткую сцену о команде, которая чинит радугу, когда на ней появляется лишний цвет.','invent a short scene about a rainbow repair team finding an extra colour.','gökkuşağında fazladan renk bulan onarım ekibi hakkında kısa bir sahne bulmayı.')
y(1025,'описать шестью словами зонт, который собирает звёзды вместо дождя.','describe in six words an umbrella that gathers stars instead of rain.','yağmur yerine yıldız toplayan şemsiyeyi altı sözcükle anlatmayı.')
y(1034,'придумать реплику чашки с витрины, которая тайно мечтает стать вазой.','invent a line for a display cup secretly dreaming of becoming a vase.','gizlice vazo olmayı düşleyen vitrindeki fincan için bir replik bulmayı.')
y(1037,'вместе описать начало, сюрприз и финал воображаемой музыкальной прогулки по облаку.','describe together the beginning, surprise, and ending of an imaginary musical walk on a cloud.','buluttaki hayali müzikli yürüyüşün başlangıcını, sürprizini ve sonunu birlikte anlatmayı.')
y(1038,'придумать два разных появления сказочного кота: под мягкий звук и под резкий; исполнение не требуется.','imagine a fairy-tale cat arriving twice, once with a gentle sound and once with a sharp one; no performance is needed.','masal kedisinin yumuşak ve keskin sesle iki farklı gelişini hayal etmeyi; ses çıkarmanız gerekmiyor.')
y(1041,'описать, как музыка в истории одинокого фонаря становится радостнее после появления звезды.','describe how music in a lonely lamp’s story grows happier when a star appears.','yalnız fenerin hikâyesinde yıldız gelince müziğin nasıl neşelendiğini anlatmayı.')
y(1044,'сравнить тембры флейты и барабана через два простых образа, например ручей и шаги великана.','compare the timbres of a flute and a drum through two simple images, such as a stream and a giant’s footsteps.','flütle davulun ses renklerini dere ve devin adımları gibi iki basit imgeyle karşılaştırmayı.')
y(1049,'придумать, кто неожиданно заглянул на воображаемый концерт внутри ореховой скорлупы.','imagine who unexpectedly visits a concert inside an imaginary nutshell.','hayali ceviz kabuğundaki konsere kimin beklenmedik biçimde geldiğini bulmayı.')
y(1053,'придумать короткую историю об исчезновении совершенно ненужной инструкции.','invent a short story about the disappearance of an entirely unnecessary instruction.','tamamen gereksiz bir yönergenin kaybolması hakkında kısa bir hikâye bulmayı.')
y(1054,'придумать две реплики разговора крышки и кастрюли о подходящем размере.','invent two lines between a lid and a saucepan about the right size.','kapak ile tencere arasında uygun boyutla ilgili iki repliklik kısa bir diyalog bulmayı.')
y(1060,'продолжить шутку «У бублика наконец нашлась пропавшая середина» одной короткой репликой.','continue the joke “A bagel has finally found its missing centre” with one short line.','“Simit sonunda kayıp ortasını buldu” şakasını kısa bir replikle sürdürmeyi.')
y(1070,'придумать, за что два друга поблагодарят друг друга после прогулки по городу перевёрнутых зонтов.','imagine what two friends thank each other for after a walk through the city of upside-down umbrellas.','ters şemsiyeler şehrinde yürüyen iki arkadaşın birbirine ne için teşekkür ettiğini bulmayı.')
y(1077,'разыграть словами сцену, где ёж предлагает белке помощь с воздушным змеем и спокойно принимает любой ответ.','roleplay in words a hedgehog offering a squirrel help with a kite and calmly accepting any answer.','kirpi sincaba uçurtma için yardım önerirken her yanıtı sakince kabul ettiği sahneyi sözcüklerle oynamayı.')
y(1078,'придумать тёплое напутствие друзьям, отправляющимся искать радугу после дождя.','invent warm parting words for friends setting out to find a rainbow after rain.','yağmurdan sonra gökkuşağı aramaya çıkan arkadaşlara sıcak bir uğurlama sözü bulmayı.')
y(1082,'придумать добрую реакцию сказочного друга на идею построить дом для эха.','invent a fairy-tale friend’s kind response to the idea of building a house for an echo.','yankıya ev yapma fikrine masal arkadaşının iyi niyetli yanıtını bulmayı.')
y(1086,'написать две вымышленные реплики: сова предлагает совет, а кот предпочитает сначала подумать сам. Это не проверка ваших личных решений.','write two fictional lines: an owl offers advice, and a cat prefers to think first. This does not test your personal decisions.','iki hayali replik yazmayı: baykuş öğüt verir, kedi önce kendisi düşünmek ister. Bu, kişisel kararlarınızı sınamaz.')
y(1090,'придумать короткий разговор двух сказочных фонарей, которые меняют тему со сплетен о вымышленном драконе на погоду.','invent a short exchange between fairy-tale lamps switching from gossip about an imaginary dragon to the weather.','hayali ejderha dedikodusundan hava durumuna geçen iki masal fenerinin kısa konuşmasını bulmayı.')
y(1096,'придумать сценку, где два сказочных героя оставляют недостроенный замок на завтра и идут смотреть звёзды.','invent a scene where two fairy-tale characters leave an unfinished castle until tomorrow and go stargazing.','yarım şatoyu yarına bırakıp yıldız izlemeye giden iki masal karakterinin sahnesini bulmayı.')
y(1111,'если оба хотите, в личном разговоре придумать добрую шутку про слишком занятую закладку. Каждый вправе убрать любую неприятную лично ему формулировку без объяснений.','if you both wish, privately invent a kind joke about an overly busy bookmark. Either person may remove wording they personally dislike without giving a reason.','ikiniz de isterseniz özel konuşmanızda fazla meşgul ayraç hakkında iyi niyetli şaka bulmayı. Her biriniz hoşunuza gitmeyen bir ifadeyi, gerekçe göstermeden çıkarabilirsiniz.')
y(1113,'если оба хотите, в личном разговоре придумать две реплики закладки и книги, которые выбирают себе выходной.','if you both wish, privately invent two lines between a bookmark and a book choosing a day off.','ikiniz de isterseniz özel konuşmanızda tatil günü seçen ayraçla kitabın iki repliğini bulmayı.')
y(1118,'если оба хотите, в личном разговоре придумать, как два друга встречают первый восход на воображаемом острове.','if you both wish, privately imagine two friends watching the first sunrise on an imaginary island.','ikiniz de isterseniz özel konuşmanızda iki arkadaşın hayali adadaki ilk gün doğumunu karşılamasını hayal etmeyi.')
y(1124,'если оба хотите, в личном разговоре придумать по одной финальной реплике для сказочной встречи; можно сразу закончить этот ход.','if you both wish, privately invent one closing line each for a fairy-tale meeting; you may end this turn straight away.','ikiniz de isterseniz özel konuşmanızda masal buluşması için birer son söz bulmayı; bu turu hemen bitirebilirsiniz.')
y(1130,'если оба хотите, в личном чате придумать по одной тёплой вывеске для воображаемой мастерской бумажных птиц.','if you both wish, each invent a welcoming sign in private chat for an imaginary paper-bird workshop.','ikiniz de isterseniz özel sohbette hayali kâğıt kuş atölyesi için samimi birer tabela yazısı bulmayı.')
y(1131,'если оба хотите, в личном чате выбрать по одному неожиданному событию для музыкальной истории и соединить их в короткий сюжет.','if you both wish, each choose an unexpected event in private chat for a musical story and combine them into a short plot.','ikiniz de isterseniz özel sohbette müzikli hikâye için birer beklenmedik olay seçip kısa olay örgüsünde birleştirmeyi.')
y(1133,'если оба хотите, в личном чате придумать, как звучала бы прогулка сказочного дирижёра по рынку дождя.','if you both wish, imagine in private chat what a fairy-tale conductor’s walk through a rain market would sound like.','ikiniz de isterseniz özel sohbette masal şefinin yağmur pazarındaki yürüyüşünün nasıl duyulacağını hayal etmeyi.')
y(1135,'если оба хотите, в личном чате обменяться короткими вопросами о воображаемой мелодии: куда она идёт и что замечает?','if you both wish, exchange short questions in private chat about an imaginary tune: where is it going and what does it notice?','ikiniz de isterseniz özel sohbette hayali melodiyle ilgili kısa sorular paylaşmayı: nereye gidiyor, ne fark ediyor?')
y(1141,'если оба хотите, в личном чате обменяться конкретными предпочтениями: какой рисунок вам приятнее представить — тихий сад или оживлённую набережную?','if you both wish, exchange concrete preferences in private chat: would you rather imagine a quiet garden or a lively waterfront?','ikiniz de isterseniz özel sohbette somut tercihlerinizi paylaşmayı: sakin bahçe mi canlı sahil mi hayal etmek daha hoş?')
y(1143,'если оба хотите, в личном чате придумать встречу путешественника и хранителя забытых снов: каждый добавляет одну реплику.','if you both wish, invent in private chat a meeting between a traveller and a keeper of forgotten dreams, adding one line each.','ikiniz de isterseniz özel sohbette yolcuyla unutulmuş rüyaların bekçisinin buluşmasını birer replik ekleyerek bulmayı.')
y(1145,'если оба хотите, в личном чате обменяться короткими фразами со смыслом «эту идею можно дополнить»; менять её на деле не требуется.','if you both wish, exchange short phrases meaning “we can still build on this idea” in private chat, without requiring anyone to change it.','ikiniz de isterseniz özel sohbette “bu fikri hâlâ geliştirebiliriz” anlamındaki kısa sözleri paylaşmayı; fikri gerçekten değiştirmeniz gerekmiyor.')
y(1148,'по желанию в личном чате придумать пример добровольной договорённости не цитировать чужие сообщения без разрешения. Это договорённость между людьми, а не техническая защита от снимков экрана или пересказа.','if you both wish, draft in private chat an example of a voluntary agreement not to quote each other’s messages without permission. This is an agreement between people, not technical protection against screenshots or retelling.','isterseniz özel sohbette birbirinizin mesajlarını izin almadan alıntılamamaya dair gönüllü bir anlaşma örneği yazmayı. Bu, kişiler arası anlaşmadır; ekran görüntüsünü veya başkasına anlatmayı teknik olarak engellemez.')
y(1150,'если оба хотите, в личном чате закончить воображаемую встречу одним спокойным словом. Ответ и объяснения не требуются.','if you both wish, close an imaginary meeting in private chat with one gentle word. No reply or explanation is required.','ikiniz de isterseniz özel sohbette hayali buluşmayı tek sakin sözcükle bitirmeyi. Yanıt veya açıklama gerekmiyor.')

# Replacement proposals offer a negotiable shared scene, rather than office/lesson work.
for n,ru,en,tr in [
 (1023,'вообразить лес, где тени меняются местами, и выбрать, какую тень каждый встретит первой.','imagine a forest where shadows swap places and choose which shadow each meets first.','gölgelerin yer değiştirdiği ormanı hayal edip her birinizin önce hangi gölgeyle karşılaşacağını seçmeyi.'),
 (1024,'придумать встречу двух потерянных носков в сказочном аэропорту.','invent a meeting of two lost socks in a fairy-tale airport.','masal havaalanında kayıp iki çorabın buluşmasını hayal etmeyi.'),
 (1026,'по очереди добавить по одной детали к истории открытки, которая сама отправилась в отпуск.','take turns adding a detail to the story of a postcard taking its own holiday.','kendi başına tatile giden kartpostalın hikâyesine sırayla birer ayrıntı eklemeyi.'),
 (1027,'выбрать по одному волшебному предмету для путешествия и придумать, как они неожиданно помогают друг другу.','each choose a magical travel object and imagine how the objects unexpectedly help each other.','yolculuk için birer sihirli nesne seçip birbirlerine beklenmedik biçimde nasıl yardım ettiklerini hayal etmeyi.'),
 (1029,'придумать короткий разговор двух крышек, которые перепутали свои банки.','invent a short conversation between two lids that have mixed up their jars.','kavanozlarını karıştıran iki kapağın kısa konuşmasını bulmayı.'),
 (1030,'выбрать, где устроить воображаемый пикник — на облаке или на гигантском листе — и добавить по одному гостю.','choose an imaginary picnic on a cloud or giant leaf and add one guest each.','hayali pikniği bulutta mı dev yaprakta mı yapacağınızı seçip birer konuk eklemeyi.'),
 (1033,'придумать, что увидят два друга внутри чемодана, который больше изнутри, чем снаружи.','imagine what two friends find in a suitcase that is bigger inside than outside.','içi dışından büyük bavulun içinde iki arkadaşın ne bulduğunu hayal etmeyi.'),
 (1035,'выбрать для вымышленного чая необычный запах и неожиданную погоду за окном.','choose an unusual scent for imaginary tea and unexpected weather outside the window.','hayali çay için sıra dışı koku ve pencere dışında beklenmedik hava seçmeyi.'),
 (1036,'по очереди придумать, во что превращается одна линия в рисунке сказочного города.','take turns imagining what one drawn line becomes in a fairy-tale city.','masal şehrinin çizimindeki tek çizginin neye dönüştüğünü sırayla hayal etmeyi.'),
 (1039,'выбрать место для концерта поющих камней и придумать по одному необычному слушателю.','choose a venue for singing stones and invent one unusual listener each.','şarkı söyleyen taşların konser yerini seçip birer sıra dışı dinleyici bulmayı.'),
 (1042,'вообразить, что одна нота сбежала гулять, и по очереди придумать два места её остановки.','imagine one note escaping for a walk and take turns choosing two stops.','bir notanın gezmeye kaçtığını hayal edip sırayla iki durak seçmeyi.'),
 (1043,'придумать короткое приветствие воображаемой радиостанции, которую слушают только облака.','invent a short greeting for an imaginary radio station heard only by clouds.','yalnız bulutların dinlediği hayali radyo istasyonu için kısa selamlama bulmayı.'),
 (1045,'придумать, какой неожиданный звук рассмешил оркестр в сказочном городе.','imagine an unexpected sound that made a fairy-tale city’s orchestra laugh.','masal şehrinin orkestrasını güldüren beklenmedik sesi hayal etmeyi.'),
 (1048,'рассказать по одному предложению истории о мелодии, которая заблудилась между этажами.','each add a sentence to a story about a tune lost between floors.','katlar arasında kaybolan melodinin hikâyesine birer cümle eklemeyi.'),
 (1052,'выбрать два сказочных звука и придумать, почему они решили путешествовать вместе.','choose two fairy-tale sounds and imagine why they decided to travel together.','iki masal sesi seçip neden birlikte yolculuk etmeye karar verdiklerini bulmayı.'),
 (1069,'выбрать, какой вымышленный клуб друзей вам интереснее: ловцов эха или хранителей рассвета.','choose which imaginary friends’ club interests you more: echo catchers or dawn keepers.','yankı avcıları mı şafak bekçileri mi, hangi hayali arkadaş kulübünün daha ilginç olduğunu seçmeyi.'),
 (1072,'придумать, какой сюрприз приготовят друг другу два садовника лунных цветов.','imagine the surprises two gardeners of lunar flowers prepare for each other.','ay çiçeği yetiştiren iki bahçıvanın birbirine hangi sürprizi hazırladığını bulmayı.'),
 (1073,'вообразить общую прогулку по лесу стеклянных листьев и добавить по одному открытию.','imagine a shared walk in a forest of glass leaves and add a discovery each.','cam yapraklı ormanda ortak yürüyüş hayal edip birer keşif eklemeyi.'),
 (1074,'придумать по одному забавному препятствию для друзей, которые идут на праздник улиток.','each invent a funny obstacle for friends heading to a snail festival.','salyangoz festivaline giden arkadaşlar için birer komik engel bulmayı.'),
 (1075,'выбрать для двух сказочных друзей разные волшебные подарки и придумать их реакцию.','choose different magical gifts for two fairy-tale friends and imagine their reactions.','iki masal arkadaşına farklı sihirli hediyeler seçip tepkilerini hayal etmeyi.'),
 (1076,'придумать две привычки друзей, живущих в городе, где вечерами летают лестницы.','invent two habits of friends living in a city where stairs fly in the evening.','akşamları merdivenlerin uçtuğu şehirdeki arkadaşların iki alışkanlığını bulmayı.'),
 (1079,'по очереди рассказать один неожиданный поворот истории дружбы чайника и маяка.','take turns adding an unexpected turn to the friendship of a kettle and a lighthouse.','çaydanlıkla deniz fenerinin arkadaşlığına sırayla beklenmedik birer olay eklemeyi.'),
 (1080,'придумать, как друзья отметят возвращение потерявшейся тени.','imagine how friends celebrate a lost shadow’s return.','arkadaşların kayıp gölgenin dönüşünü nasıl kutladığını hayal etmeyi.'),
 (1081,'выбрать два разных маршрута сказочной прогулки и придумать место встречи в конце.','choose two different fairy-tale walking routes and imagine a meeting place at the end.','iki farklı masal yürüyüşü rotası seçip sonunda buluşulacak yeri hayal etmeyi.'),
 (1084,'придумать общий финал сказочного путешествия: каждый добавляет одну приятную неожиданность.','invent a shared ending to a fairy-tale journey, adding one pleasant surprise each.','masal yolculuğuna birer hoş sürpriz ekleyerek ortak son bulmayı.'),
 (1142,'если оба хотите, в личном чате выбрать по одному месту для воображаемого вечера друзей и соединить их тайным проходом.','if you both wish, each choose a place in private chat for an imaginary evening with friends and connect them by a secret passage.','ikiniz de isterseniz özel sohbette hayali arkadaş akşamı için birer yer seçip bunları gizli geçitle birleştirmeyi.'),
 (1144,'если оба хотите, в личном чате придумать встречу двух друзей, один из которых умеет собирать эхо, а другой — хранить рассвет.','if you both wish, imagine in private chat two friends meeting, one able to gather echoes and the other to keep dawn.','ikiniz de isterseniz özel sohbette biri yankı toplayan, diğeri şafağı saklayan iki arkadaşın buluşmasını hayal etmeyi.'),
]: y(n,ru,en,tr)

# Explicit public rewrites keep the neutral idea but remove the private-channel promise.
for n,ru,en,tr in [
 (1101,('Какая перемена в картинке кажется каждому из вас успокаивающей?','Придумайте по одной детали для рисунка тихой веранды.'),('Which change in a picture feels calming to each of you?','Invent one detail each for a drawing of a quiet veranda.'),('Resimdeki hangi değişiklik her birinize huzur verir?','Sakin veranda resmi için birer ayrıntı bulun.')),
 (1102,('Какое мягкое освещение каждый выбрал бы для вымышленной комнаты?','Опишите вместе настольный светильник, не называя цветов.'),('Which soft lighting would each choose for an imaginary room?','Describe a desk lamp together without naming colours.'),('Hayali oda için her biriniz hangi yumuşak ışığı seçer?','Renk adı kullanmadan masa lambasını birlikte anlatın.')),
 (1103,('Какой простой предмет каждый рассматривал бы на рисунке крупным планом?','Придумайте необычное название для крупного рисунка чайного листа.'),('Which simple object would each enjoy seeing drawn in close-up?','Invent an unusual title for a close-up drawing of a tea leaf.'),('Her biriniz hangi basit nesnenin yakın plan çizimine bakmak ister?','Çay yaprağının yakın plan çizimine sıra dışı başlık bulun.')),
 (1105,('Какое занятие с бумагой каждому интересно представить?','Придумайте словесный макет маленькой открытки без имён и адресов.'),('Which paper activity would each enjoy imagining?','Invent a verbal design for a small card without names or addresses.'),('Kâğıtla ilgili hangi etkinliği hayal etmek her birinize ilginç gelir?','Ad ve adres olmadan küçük kartın sözel taslağını oluşturun.')),
 (1119,('Что сказочному гостю интереснее: смотреть на фокусы или показывать их?','Придумайте реплику сказочного гостя, который предпочитает пока наблюдать.'),('Would a fairy-tale guest rather watch magic tricks or perform them?','Invent a line for a fairy-tale guest who prefers to watch for now.'),('Masal konuğu sihirbazlığı izlemek mi yapmak mı ister?','Şimdilik izlemek isteyen masal konuğunun repliğini bulun.')),
 (1126,('Какое слово о погоде каждый считает особенно образным?','По очереди добавьте по одному слову к подписи воображаемой фотографии.'),('Which weather word does each of you find especially evocative?','Take turns adding one word each to an imaginary photograph’s caption.'),('Hava hakkında hangi sözcüğü her biriniz özellikle canlı bulur?','Hayali fotoğrafın alt yazısına sırayla birer sözcük ekleyin.')),
 (1127,('Какой короткий заголовок о растениях каждому любопытно прочитать?','Придумайте по одной строке о воображаемой выставке листьев; реальные адреса не нужны.'),('Which short heading about plants would each be curious to read?','Invent one line each about an imaginary leaf exhibition; no real addresses are needed.'),('Bitkilerle ilgili hangi kısa başlığı her biriniz merakla okur?','Hayali yaprak sergisi hakkında birer satır bulun; gerçek adres gerekmiyor.')),
 (1128,('Как каждый описал бы форму снежинки в одну строку?','По очереди добавьте по слову к описанию снежинки, не больше четырёх слов всего.'),('How would each describe a snowflake’s shape in one line?','Take turns adding a word to a snowflake description, four words at most in total.'),('Kar tanesinin biçimini her biriniz tek satırda nasıl anlatır?','Kar tanesini anlatmak için sırayla birer sözcük ekleyin; toplam en çok dört sözcük olsun.')),
 (1129,('Какое короткое имя для вымышленного чая каждому кажется приятным?','Придумайте по одному названию чая и сохраните оба без голосования.'),('Which short name for imaginary tea does each find pleasant?','Invent one tea name each and keep both without voting.'),('Hayali çaya hangi kısa adı her biriniz hoş bulur?','Birer çay adı bulup oylamadan ikisini de koruyun.')),
]:
 for field,index in [('truth',0),('dare',1)]:
  td(n,field,'{P1} и {P2}, если оба согласны: '+ru[index],'{P1} and {P2}, if you both agree: '+en[index],'{P1} ve {P2}, ikiniz de kabul ederseniz: '+tr[index])

y(1009,'придумать короткое знакомство чайника и зонта. Можно написать две реплики вместо устного исполнения.','invent a short introduction between a kettle and an umbrella. You may write two lines instead of performing aloud.','çaydanlıkla şemsiyenin kısa tanışmasını bulmayı. Sesli oynamak yerine iki replik yazabilirsiniz.')
y(1071,'если оба согласны участвовать, придумать порядок обмена фантазийными историями; можно пропустить участие без объяснений.','if you both agree to take part, imagine an order for sharing fantasy stories; either may skip without a reason.','ikiniz de katılmayı kabul ederseniz hayali hikâyeleri paylaşma sırası bulmayı; her biriniz gerekçesiz geçebilirsiniz.')
for n,ru,en,tr in [
 (1101,'выбрать по одному приятному образу для воображаемого уголка чтения и при желании соединить их.','each choose a pleasant image for an imaginary reading corner and optionally combine them.','hayali okuma köşesi için birer hoş imge seçip isterseniz birleştirmeyi.'),
 (1103,'поделиться по одному общему впечатлению от запаха свежего хлеба; личные истории не нужны.','share one general impression each of fresh bread’s smell; no personal story is needed.','taze ekmek kokusuyla ilgili birer genel izlenim paylaşmayı; kişisel öykü gerekmiyor.'),
 (1105,'придумать маленькую коллекцию из трёх приятных слов о природе.','invent a small collection of three pleasant words about nature.','doğayla ilgili hoş üç sözcüklük küçük seçki bulmayı.'),
 (1106,'словами описать музыку для приятной паузы и найти общее настроение; запись включать не нужно.','describe music for a pleasant pause in words and find a shared mood; no recording is needed.','hoş mola müziğini sözcüklerle anlatıp ortak duygu bulmayı; kayıt açmanız gerekmiyor.'),
 (1120,'придумать сценку, где сказочный гость выбирает между участием в фокусе и наблюдением.','invent a scene where a fairy-tale guest chooses between joining a magic trick and watching it.','masal konuğunun sihirbazlığa katılmakla izlemek arasında seçim yaptığı sahneyi bulmayı.'),
 (1126,'придумать по одному началу названия вымышленного сада и при желании соединить их.','each invent an opening for an imaginary garden’s name and optionally combine them.','hayali bahçe adına birer başlangıç bulup isterseniz birleştirmeyi.'),
 (1127,'обменяться двумя короткими подписями к воображаемому рисунку ракушки, не выбирая лучшую.','exchange two short captions for an imaginary shell drawing without choosing the best.','hayali deniz kabuğu çizimine iki kısa yazı paylaşıp en iyisini seçmemeyi.'),
 (1128,'придумать трёхстрочный мини-путеводитель по нарисованной полке; реальные вещи и адреса не нужны.','invent a three-line mini-guide to a drawn shelf; no real possessions or addresses are needed.','çizili rafın üç satırlık küçük rehberini bulmayı; gerçek eşya veya adres gerekmiyor.'),
 (1129,'добавить по одному слову к словесной коллекции круглых предметов.','add one word each to a verbal collection of round objects.','yuvarlak nesnelerin sözel seçkisine birer sözcük eklemeyi.'),
]: y(n,'если оба согласны: '+ru,'if you both agree: '+en,'ikiniz de kabul ederseniz: '+tr)

if __name__=='__main__':
    OUT.joinpath('text-overrides.json').write_text(json.dumps(changes,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
    groups=[
      ('SKIP','Q-1017 Q-1086 Q-1099 Q-1146 TD-1019 TD-1093 TD-1095 TD-1122 YB-1017 YB-1019 YB-1020 YB-1087 YB-1088 YB-1093 YB-1097 YB-1122 YB-1147','В каждом раунде и приватном предложении доступны равноправные действия «Ответить/принять» и «Пропустить/отказаться». Отказ и пропуск не требуют причины, публичного ответа, штрафа или придумывания специальной фразы; можно пропустить несколько следующих раундов.','Отказаться с пустым reason, пропустить два раунда; состояние корректно, объяснение не запрошено, участникам не показывается мотив, счёт/ценность игрока не снижается.'),
      ('WAIT','Q-1020 Q-1085 Q-1090 Q-1124 TD-1087 TD-1091 TD-1099 TD-1146 YB-1018 YB-1083','Явное состояние «Пока не выбираю/пауза» не является согласием. Оно не создаёт обещания вернуться к сроку или обязательства участвовать позже. UI предлагает спокойный выбор без давления и автоматического принятия.','Оставить приглашение pending, сделать паузу, не возвращаться; выполнение не начинается, таймер/следующее событие не превращает pending в accepted.'),
      ('NO_REASON','Q-1096 Q-1148 TD-1090 YB-1092','Уточнение условий и отказ не требуют раскрытия личных мотивов. Приложение не объясняет отказ одного игрока другому и не публикует частные причины без его разрешения.','Запросить уточнение без пояснения; данные причин отсутствуют в публичных HTTP/WS проекциях и сообщениях другим игрокам.'),
      ('NO_PERSONAL_STORY','Q-1088 TD-1088 YB-1098','Личная история или реальный пример всегда добровольны; доступна вымышленная/общая альтернатива либо пропуск без проверки достоверности и объяснений.','Выбрать вымышленный ответ или пропуск; форма не требует личных данных, доказательств или публичного обоснования.'),
      ('PER_ACTION','Q-1092 Q-1100 TD-1092 YB-1094','Участие в комнате, игре или прошлом раунде не даёт согласия на следующий раунд или конкретное действие. Решение каждого участника сохраняется отдельно; согласие одного не заменяет другого.','P1 принимает, P2 pending/отказывается; переход к выполнению запрещён. Новое предложение не наследует прежнее принятие.'),
      ('DECLINE_PERSISTS','Q-1091 YB-1099','Первичный отказ остаётся действительным при обсуждении альтернативы. Предложенное ограничение не ослабляется автоматически и не запускает торг, повторное давление или автоматическое принятие.','После declined предложить альтернативу; исходное предложение остаётся declined, альтернативе нужны новые свободные решения обоих.'),
      ('SILENCE','Q-1095 TD-1094','Молчание и отсутствие ответа не считаются согласием или завершённым ответом. Переходы выполняются только после явного действия пользователя.','Не отвечать до и после таймаута; ни accepted, ни выполнение не возникают.'),
      ('WITHDRAW','Q-1097 TD-1121 TD-1125 TD-1149 TD-1150','Каждый может отозвать прежнее согласие, прервать действие или сменить нежелательную тему без торга, оправданий и итогового отчёта. Остановка доступна непосредственным действием UI, включая приватную беседу.','Отозвать согласие после принятия; дальнейшее действие блокируется и прекращается, обязательного текста в чате/отчёта нет.'),
      ('TOPIC_BOUNDARY','Q-1121 Q-1122 TD-1123 YB-1121','До приватной беседы доступны выбор допустимых тем и непосредственная смена вопроса. Исключённые темы не требуют объяснений и не раскрываются группе; продолжение беседы не расширяет границы автоматически.','Один игрок исключает тему, затем запрашивает другой вопрос; прежняя тема не выдаётся снова, её название и мотив не публикуются другим.'),
      ('IDEA_ONLY','Q-1128 Q-1144 TD-1148','UI различает предложенную/сохранённую идею, обсуждение её формулировки и принятое действие. Сохранение, редактирование или обсуждение текста не создаёт обязательства и не запускает выполнение.','Сохранить и обсудить идею без принятия; отдельные поля принятия остаются false/pending.'),
      ('READ_NOT_ACCEPT','Q-1147 TD-1147 YB-1149','Получение, доставка и прочтение сообщения отделены от принятия предложения; подтверждение доставки/прочтения никогда не меняет согласие.','Доставить и прочитать приглашение; receipt изменился, consent не изменился.'),
      ('CHANGED_CONDITION','Q-1149 TD-1100 YB-1085 YB-1125','Любое изменённое условие образует новую редакцию предложения и требует свободного повторного решения P1 и P2. Выполнение разрешено только после явного подтверждения обоих одной и той же редакции.','P2 добавляет условие; старые confirmations недействительны, P1 вправе отказаться. Разные версии условий/одно подтверждение не запускают действие.'),
      ('SHOW_SCOPE','TD-1097 YB-1089','Полные условия и пределы предложения доступны до принятия; можно запросить уточнение, оставаясь без согласия на действие.','Открыть условия и уточнить их до выбора; приложение не принимает предложение от одного открытия формы.'),
      ('ADVICE_OPT_IN','TD-1098','Подсказка или совет не раскрывается до разрешения адресата. Отказ оставляет совет скрытым и не требует причины.','Отказать в подсказке; текст совета отсутствует в проекциях адресата и комнаты.'),
      ('NEW_INVITATION','TD-1124 YB-1123 YB-1146','Новое приглашение или тема требует собственного явного согласования. Текущее присутствие, переписка и готовность к прежней теме не означают готовности к новой.','Во время активного чата создать новую тему; оба участника получают самостоятельный выбор, новое действие остаётся pending.'),
      ('NO_SOCIAL_PRESSURE','YB-1091','Основной UX не подталкивает к согласию фразами «все уже согласились», «только ты остался» или публичным объяснением задержки/отказа.','Проверить RU/EN/TR все состояния ожидания/отказа; отсутствуют сравнение с другими и сообщения о том, кто задерживает согласие.'),
      ('REVIEW_TERMS','YB-1095','Перед выполнением обоим показана одна актуальная редакция согласованных условий; подтверждения связаны с её идентификатором/хешем.','Одновременно изменить условие и подтвердить старую редакцию; старое подтверждение отклоняется, выполнение не начинается.'),
      ('NO_AGREEMENT_END','YB-1100','Завершить обсуждение без итогового согласия — нормальная терминальная ветвь; интерфейс не требует найти компромисс для выхода.','Закрыть обсуждение с несовпадающими решениями; оба могут выйти, выполнение не запускается.'),
      ('TASTES','Q-1049','Правила комнаты и модерационные подсказки допускают разные музыкальные вкусы; отсутствие совпадения не становится оценкой/штрафом игрока и не требует спора.','Выбрать несовпадающие вкусы и пропустить обсуждение; нет штрафа, обязательного оправдания или повторного давления.'),
    ]
    requirements=[{'id':'P04-UX-'+key,'source_card_ids':ids.split(),'requirement':requirement,'acceptance_scenario':test,'implementation_status':'NOT_IMPLEMENTED_BY_THIS_CHANGE','test_status':'NOT_RUN_BY_THIS_CONTENT_PROCESSOR'} for key,ids,requirement,test in groups]
    OUT.joinpath('product-ux-requirements.json').write_text(json.dumps({'schema_version':1,'scope':'Concrete extracted requirements, not implemented UI','requirements':requirements},ensure_ascii=False,indent=2)+'\n',encoding='utf8')
    print(len(changes))
